# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# validate_maturity_at_age ----
## Setup ----
data("data_big")
data_4_model <- FIMSFrame(data_big)
ages <- get_ages(data_4_model)
years <- get_start_year(data_4_model):get_end_year(data_4_model)

maturity_rows <- function(timing = NA_real_, age = ages,
                          observed = stats::plogis(age - 2)) {
  tibble::tibble(
    type = "maturity_at_age",
    fleet = NA_character_,
    age = age,
    length = NA_real_,
    timing = timing,
    observed = observed,
    unit = "proportion",
    uncertainty = NA_character_
  )
}

# Builds a FIMSFrame from data_big plus maturity rows, so the checks in
# validate_at_age_input() and validate_maturity_at_age() both run
frame_with_maturity <- function(...) {
  FIMSFrame(dplyr::bind_rows(data_big, ...))
}

## IO correctness ----
test_that("validate_maturity_at_age() works with correct inputs", {
  #' @description Test that one row per age with timing = NA is valid.
  expect_true(validate_maturity_at_age(maturity_rows()))

  #' @description Test that data without maturity_at_age rows are valid.
  expect_true(validate_maturity_at_age(data_big))

  #' @description Test that maturity of exactly 0 and 1 is valid.
  expect_true(validate_maturity_at_age(
    maturity_rows(observed = c(0, rep(1, length(ages) - 1)))
  ))
})

test_that("FIMSFrame() accepts valid maturity_at_age rows", {
  #' @description Test that a timing = NA default plus 1 year of overrides is valid.
  expect_s4_class(
    frame_with_maturity(maturity_rows(), maturity_rows(timing = years[2])),
    "FIMSFrame"
  )

  #' @description Test that rows for every model year and the year after the last, without a default, are valid.
  all_years <- purrr::map(
    c(years, max(years) + 1),
    \(year) maturity_rows(timing = year)
  ) |>
    dplyr::bind_rows()
  expect_s4_class(frame_with_maturity(all_years), "FIMSFrame")

  #' @description Test that zero maturity at only some ages is valid.
  expect_s4_class(
    frame_with_maturity(
      maturity_rows(observed = c(0, 0, stats::plogis(ages[-(1:2)] - 2)))
    ),
    "FIMSFrame"
  )
})

## Edge handling ----
test_that("FIMSFrame() keeps the model years when maturity_at_age is added", {
  data_with_maturity <- frame_with_maturity(
    maturity_rows(),
    maturity_rows(timing = max(years) + 1)
  )

  #' @description Test that maturity_at_age rows, including the year after the last model year, do not change the model years or ages.
  expect_equal(get_n_years(data_with_maturity), get_n_years(data_4_model))
  expect_equal(get_end_year(data_with_maturity), max(years))
  expect_equal(get_ages(data_with_maturity), ages)
})

## Error handling ----
test_that("validate_maturity_at_age() returns correct error messages", {
  #' @description Test that values above 1 return an error that names them.
  expect_error(
    validate_maturity_at_age(maturity_rows(observed = 1.5)),
    "values above 1.*1.5"
  )

  #' @description Test that a unit other than proportion returns an error that names it.
  expect_error(
    validate_maturity_at_age(dplyr::mutate(maturity_rows(), unit = "number")),
    "units other than.*number"
  )
})

test_that("FIMSFrame() returns correct maturity_at_age error messages", {
  #' @description Test that -999 returns an error rather than being treated as missing data.
  expect_error(
    frame_with_maturity(maturity_rows(observed = -999)),
    "missing or negative"
  )

  #' @description Test that a fleet-specific row returns an error.
  expect_error(
    frame_with_maturity(dplyr::mutate(maturity_rows(), fleet = "fleet1")),
    "fleet = NA"
  )

  #' @description Test that a timing 2 years after the last model year returns an error.
  expect_error(
    frame_with_maturity(
      maturity_rows(),
      maturity_rows(timing = max(years) + 2)
    ),
    "years outside"
  )

  #' @description Test that a timing missing an age returns an error.
  expect_error(
    frame_with_maturity(
      maturity_rows(),
      maturity_rows(timing = years[2], age = ages[-1])
    ),
    "missing ages for these timings"
  )

  #' @description Test that a duplicated age returns an error.
  expect_error(
    frame_with_maturity(maturity_rows(), maturity_rows(age = ages[1])),
    "Only one row"
  )

  #' @description Test that zero maturity at every age in 1 year returns an error because spawning output would be 0.
  expect_error(
    frame_with_maturity(
      maturity_rows(),
      maturity_rows(timing = years[2], observed = 0)
    ),
    "0 at every age"
  )

  #' @description Test that rows for every model year but not the year after the last return an error without a timing = NA default.
  model_years_only <- purrr::map(years, \(year) maturity_rows(timing = year)) |>
    dplyr::bind_rows()
  expect_error(
    frame_with_maturity(model_years_only),
    paste0("missing these years.*", max(years) + 1)
  )
})
